#include <Aevrynd/Renderer.h>
#include <Aevrynd/Camera.h>
#include <cmath>
#include <cstring>
#include <iostream>
#include <limits>

using namespace Aevrynd;

int main(){
    SoftDirectionalShadowSettings3D defaults{};
    if(!defaults.enabled||defaults.blockerSearchRadiusTexels!=24.f||defaults.lightSourceRadiusTexels!=128.f||defaults.maximumPenumbraRadiusTexels!=32.f){std::cerr<<"Soft shadow defaults failed\n";return 1;}
    SoftDirectionalShadowSettings3D invalid{true,std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity(),-8.f};
    invalid=NormalizeSoftDirectionalShadowSettings3D(invalid);
    if(invalid.blockerSearchRadiusTexels!=24.f||invalid.lightSourceRadiusTexels!=128.f||invalid.maximumPenumbraRadiusTexels!=1.45f){std::cerr<<"Soft shadow normalization failed\n";return 2;}
    const float contact=DirectionalShadowPenumbraRadius3D(.5001f,.5f,defaults),separated=DirectionalShadowPenumbraRadius3D(.55f,.5f,defaults),maximum=DirectionalShadowPenumbraRadius3D(.95f,.1f,defaults);
    if(contact!=1.45f||!(separated>contact&&separated<maximum)||maximum!=32.f){std::cerr<<"Contact-hardening response failed "<<contact<<'/'<<separated<<'/'<<maximum<<'\n';return 3;}
    defaults.enabled=false;
    if(DirectionalShadowPenumbraRadius3D(.9f,.1f,defaults)!=1.45f){std::cerr<<"Disabled soft shadow changed PCF radius\n";return 4;}
    DrawList draw;
    draw.SetSoftDirectionalShadows({true,99.f,-4.f,99.f});
    const auto state=draw.SoftDirectionalShadows();
    if(state.blockerSearchRadiusTexels!=24.f||state.lightSourceRadiusTexels!=1.f||state.maximumPenumbraRadiusTexels!=32.f){std::cerr<<"Draw-list soft shadow state failed\n";return 5;}
    DirectionalShadowCascadeSettings3D cascades{4,4096,.1f,200.f,.65f,.1f};
    cascades=NormalizeDirectionalShadowCascadeSettings3D(cascades);
    const auto splits=DirectionalShadowPracticalSplits3D(cascades);
    const auto oversized=NormalizeDirectionalShadowCascadeSettings3D({4,8192,.1f,200.f,.65f,.1f});
    const auto oversizedSplits=DirectionalShadowPracticalSplits3D({4,8192,.1f,200.f,.65f,.1f});
    const auto uniformSplits=DirectionalShadowPracticalSplits3D({4,4096,.1f,200.f,0.f,.1f});
    const auto logarithmicSplits=DirectionalShadowPracticalSplits3D({4,4096,.1f,200.f,1.f,.1f});
    // 4096 是 DevelopmentUltra 的正式陰影解析度；解析度不得改變實際分割距離。
    if(cascades.resolution!=4096||oversized.resolution!=4096||splits!=oversizedSplits||splits[3]!=200.f||!(splits[0]>.1f&&splits[0]<splits[1]&&splits[1]<splits[2]&&splits[2]<splits[3])||!(logarithmicSplits[0]<splits[0]&&splits[0]<uniformSplits[0])){std::cerr<<"Practical cascade splits failed resolution="<<cascades.resolution<<" oversized="<<oversized.resolution<<" splits="<<splits[0]<<','<<splits[1]<<','<<splits[2]<<','<<splits[3]<<" uniform0="<<uniformSplits[0]<<" logarithmic0="<<logarithmicSplits[0]<<'\n';return 6;}
    for(uint32_t index=0;index<4;++index){const float sample=index?splits[index-1]:.1f;if(SelectDirectionalShadowCascade3D(sample,splits,4)!=index){std::cerr<<"Cascade exact boundary selection failed index="<<index<<" sample="<<sample<<'\n';return 7;}if(index&&SelectDirectionalShadowCascade3D(std::nextafter(splits[index-1],0.f),splits,4)!=index-1){std::cerr<<"Cascade lower boundary selection failed index="<<index<<'\n';return 7;}}
    const float texel=80.f*2.f/2048.f,snapped=SnapDirectionalShadowCoordinate3D(13.237f,texel);if(std::abs(snapped/texel-std::round(snapped/texel))>1e-5f){std::cerr<<"Cascade texel snapping failed\n";return 8;}
    draw.SetDirectionalShadowCascades({0,1,std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity(),-1.f,2.f});
    if(draw.DirectionalShadowCascades().cascadeCount!=1||draw.DirectionalShadowCascades().resolution!=512||draw.DirectionalShadowCascades().nearDistance!=.1f||draw.DirectionalShadowCascades().farDistance!=180.f){std::cerr<<"Cascade settings normalization failed\n";return 9;}
    draw.SetContactShadows({true,99,std::numeric_limits<float>::infinity(),-1.f,2.f});const auto contactSettings=draw.ContactShadows();if(contactSettings.maximumSteps!=24||contactSettings.maximumDistance!=1.5f||contactSettings.thickness!=.001f||contactSettings.strength!=1.f){std::cerr<<"Contact shadow normalization failed\n";return 10;}
    Matrix4 perspective=Matrix4::Identity();perspective[3][0]=0;perspective[3][1]=0;perspective[3][2]=1;perspective[3][3]=0;Matrix4 orthographic=Matrix4::Identity();orthographic[2][0]=0;orthographic[2][1]=0;orthographic[2][2]=.01f;const Vec3 camera{0,0,-5};for(const Matrix4& projection:{perspective,orthographic}){const float center=DirectionalShadowLinearDepth3D(projection,{0,0,15},camera),edge=DirectionalShadowLinearDepth3D(projection,{100,80,15},camera),nearDepth=DirectionalShadowLinearDepth3D(projection,{0,0,-4},camera);if(std::abs(center-20.f)>.001f||std::abs(edge-center)>.001f||std::abs(nearDepth-1.f)>.001f){std::cerr<<"Perspective/orthographic linear depth failed\n";return 11;}}
    DirectionalShadowCascadeSettings3D bandSettings{4,2048,.1f,100.f,0.f,.05f};const std::array<float,4> bandSplits{10,30,60,100};const uint8_t nearMask=DirectionalShadowDepthBandMask3D(3.f,1.f,bandSplits,bandSettings),crossMask=DirectionalShadowDepthBandMask3D(10.f,2.f,bandSplits,bandSettings),farMask=DirectionalShadowDepthBandMask3D(80.f,1.f,bandSplits,bandSettings);if(nearMask!=1u||crossMask!=(1u|2u)||farMask!=8u||DirectionalShadowDepthBandMask3D(std::numeric_limits<float>::quiet_NaN(),1.f,bandSplits,bandSettings)!=DirectionalShadowAllCascades3D){std::cerr<<"Automatic depth-band caster masks failed\n";return 12;}
    const auto verifyFit=[](Camera3D fitCamera,float aspect){const DirectionalShadowCascadeSettings3D settings{4,2048,.1f,180.f,.65f,.08f};const auto fit=FitDirectionalShadowCascades3D(CreateViewProjectionMatrix(fitCamera,aspect),fitCamera.position,{.42f,-1.f,.27f},settings,40.f,6.f);if(!fit.valid||fit.fallback||fit.reversedDepth)return false;for(uint32_t cascade=0;cascade<settings.cascadeCount;++cascade){for(Vec3 corner:fit.sliceCorners[cascade]){const Vec4 clip=fit.lightViewProjections[cascade]*Vec4{corner.x,corner.y,corner.z,1};if(!std::isfinite(clip.x)||!std::isfinite(clip.y)||!std::isfinite(clip.z)||std::abs(clip.w-1.f)>1e-4f||std::abs(clip.x)>1.0001f||std::abs(clip.y)>1.0001f||clip.z<-.0001f||clip.z>1.0001f)return false;}if(cascade)for(size_t corner=0;corner<4;++corner)if(Length(fit.sliceCorners[cascade-1][corner+4]-fit.sliceCorners[cascade][corner])>.002f)return false;}const Vec3 farReceiver=fit.sliceCorners[3][7];const Vec4 farClip=fit.lightViewProjections[3]*Vec4{farReceiver.x,farReceiver.y,farReceiver.z,1};const Vec3 farCaster=farReceiver-Normalize(Vec3{.42f,-1.f,.27f})*32.f;const Vec4 casterClip=fit.lightViewProjections[3]*Vec4{farCaster.x,farCaster.y,farCaster.z,1};return farClip.z>=0&&farClip.z<=1&&casterClip.z>=0&&casterClip.z<=1;};
    Camera3D fitPerspective{{17.f,9.f,-23.f},{-4.f,3.f,31.f},{.1f,1.f,.05f},{ProjectionMode::Perspective,1.42f,20.f,.05f,500.f}};if(!verifyFit(fitPerspective,3.55f)){std::cerr<<"Perspective cascade frustum fit failed\n";return 13;}Camera3D fitOrthographic{{-37.f,54.f,-19.f},{8.f,-3.f,42.f},{0,1,0},{ProjectionMode::Orthographic,1.f,87.f,.2f,600.f}};if(!verifyFit(fitOrthographic,.31f)){std::cerr<<"Orthographic cascade frustum fit failed\n";return 14;}
    const auto stableA=FitDirectionalShadowCascades3D(CreateViewProjectionMatrix(fitPerspective,16.f/9.f),fitPerspective.position,{.42f,-1.f,.27f},{4,2048,.1f,180.f,.65f,.08f});fitPerspective.position.x+=.000001f;fitPerspective.target.x+=.000001f;const auto stableB=FitDirectionalShadowCascades3D(CreateViewProjectionMatrix(fitPerspective,16.f/9.f),fitPerspective.position,{.42f,-1.f,.27f},{4,2048,.1f,180.f,.65f,.08f});if(!stableA.valid||!stableB.valid||std::memcmp(&stableA.lightViewProjections[3],&stableB.lightViewProjections[3],sizeof(Matrix4))!=0){std::cerr<<"Cascade texel stabilization failed\n";return 15;}
    Matrix4 singular{};const auto singularFit=FitDirectionalShadowCascades3D(singular,{},{.4f,-1,.2f});CameraProjection reversedProjection{ProjectionMode::Perspective,1.f,20.f,.1f,100.f};Matrix4 reversed=CreateProjectionMatrix(reversedProjection,1.f);reversed[2][2]=reversedProjection.nearPlane/(reversedProjection.nearPlane-reversedProjection.farPlane);reversed[2][3]=-reversedProjection.nearPlane*reversedProjection.farPlane/(reversedProjection.nearPlane-reversedProjection.farPlane);const Camera3D reversedCamera{{0,0,0},{0,0,1},{0,1,0},reversedProjection};const auto reversedFit=FitDirectionalShadowCascades3D(reversed*CreateViewMatrix(reversedCamera),reversedCamera.position,{.4f,-1,.2f},{4,2048,.1f,90.f,.65f,.08f});bool reversedContained=reversedFit.valid&&reversedFit.reversedDepth;for(uint32_t cascade=0;cascade<4&&reversedContained;++cascade)for(Vec3 value:reversedFit.sliceCorners[cascade]){const Vec4 clip=reversedFit.lightViewProjections[cascade]*Vec4{value.x,value.y,value.z,1};reversedContained&=std::abs(clip.x)<=1.0001f&&std::abs(clip.y)<=1.0001f&&clip.z>=-.0001f&&clip.z<=1.0001f;}if(singularFit.valid||!singularFit.fallback||!reversedContained){std::cerr<<"Invalid fallback or reversed-depth support failed singular="<<singularFit.valid<<'/'<<singularFit.fallback<<" reversed="<<reversedFit.valid<<'/'<<reversedFit.fallback<<'/'<<reversedFit.reversedDepth<<'\n';return 16;}
    std::cout<<"Aevrynd soft directional shadow smoke passed contact="<<contact<<" separated="<<separated<<" maximum="<<maximum<<'\n';
    return 0;
}
